/* Full-page exploration layer. All activity below is explicitly fictional. */
(() => {
  'use strict';
  const C = window.Clareia;
  const { compact, money, number, escape: esc, icon } = C;
  const $ = s => document.querySelector(s);
  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  const months = window.ClareiaData.monthNames;
  const read = (key, fallback) => { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } };
  const save = (key, value) => { try { localStorage.setItem(key, JSON.stringify(value)); } catch { C.toast('O navegador não permitiu salvar. A seleção continua disponível nesta visita.'); } };
  const state = {
    highlightCategory: null, month: 12, mapUF: 'SP', mapMetric: 'total', from: 1, to: 12, a: 'ana', b: 'bruno', topic: 'Todos', stage: 'Todos', projectQuery: '', voter: 'ana', timeline: 'ana', rosterQuery: '', rosterUF:'Todos', rosterParty:'Todos',
    favorites: new Set((Array.isArray(read('clareia-favorites', [])) ? read('clareia-favorites', []) : []).filter(id => C.person(id))),
    projects: new Set((Array.isArray(read('clareia-projects', [])) ? read('clareia-projects', []) : []).filter(id => ['01', '02', '03', '04'].includes(id))),
    motion: !reduced.matches && read('clareia-motion', true) !== false
  };
  const UF = {
    AC: ['Acre',0,2], RO:['Rondônia',2,2], AM:['Amazonas',3,1], RR:['Roraima',4,0], PA:['Pará',5,1], AP:['Amapá',6,0],
    MT:['Mato Grosso',4,2], TO:['Tocantins',6,2], MA:['Maranhão',7,1], PI:['Piauí',8,2], CE:['Ceará',9,1], RN:['Rio Grande do Norte',11,1],
    PB:['Paraíba',12,2], PE:['Pernambuco',10,2], AL:['Alagoas',11,3], SE:['Sergipe',9,3], BA:['Bahia',7,3], GO:['Goiás',5,3], DF:['Distrito Federal',6,4],
    MS:['Mato Grosso do Sul',4,4], MG:['Minas Gerais',8,4], ES:['Espírito Santo',10,4], SP:['São Paulo',7,5], RJ:['Rio de Janeiro',9,5],
    PR:['Paraná',5,5], SC:['Santa Catarina',6,6], RS:['Rio Grande do Sul',5,7]
  };
  const projects = [
    { id:'01', title:'Dados públicos que qualquer pessoa consegue entender.', topic:'Transparência', author:'ana', stage:'Em análise', step:2, summary:'Propõe linguagem simples e formatos acessíveis na publicação de informações públicas.', date:'12 de março', trail:['Apresentado','Distribuído à comissão','Em análise','Votação','Conclusão'] },
    { id:'02', title:'Conectividade e formação digital nas escolas.', topic:'Educação', author:'bruno', stage:'Em votação', step:3, summary:'Propõe um programa demonstrativo de formação de professores e acesso a recursos digitais.', date:'8 de maio', trail:['Apresentado','Parecer emitido','Comissão concluída','Em votação','Conclusão'] },
    { id:'03', title:'Acesso sem barreiras aos serviços digitais.', topic:'Acessibilidade', author:'carla', stage:'Aprovado na Câmara', step:4, summary:'Propõe requisitos de acessibilidade para interfaces de serviços públicos. A aprovação nesta Casa não equivale a uma lei em vigor.', date:'19 de agosto', trail:['Apresentado','Parecer emitido','Comissão concluída','Votado','Enviado ao Senado'] },
    { id:'04', title:'Monitoramento aberto da qualidade da água.', topic:'Meio ambiente', author:'fernanda', stage:'Em análise', step:1, summary:'Propõe a publicação periódica de indicadores de qualidade da água em formatos reutilizáveis.', date:'4 de setembro', trail:['Apresentado','Distribuído à comissão','Em análise','Votação','Conclusão'] }
  ];
  const votes = [
    { id:'v1', project:'01', title:'Publicação de dados em linguagem simples', desc:'Votação do texto-base na comissão — uma etapa do projeto.', choices:{ana:'Sim',bruno:'Sim',carla:'Sim',diego:'Não',fernanda:'Abstenção'} },
    { id:'v2', project:'02', title:'Formação digital nas escolas', desc:'Destaque ao texto: mudança no cronograma de implantação.', choices:{ana:'Não',bruno:'Sim',carla:'Sim',diego:'Ausente',fernanda:'Sim'} },
    { id:'v3', project:'03', title:'Acessibilidade nos serviços digitais', desc:'Votação do texto-base na Câmara, antes do envio ao Senado.', choices:{ana:'Sim',bruno:'Sim',carla:'Sim',diego:'Sim',fernanda:'Ausente'} }
  ];
  const color = ['var(--accent)','var(--chart2)','var(--chart3)'];
  const parties = {ana:'PA',bruno:'PB',carla:'PC',diego:'PA',fernanda:'PB'};
  const scopePeople = () => C.all().filter(p => C.state.uf === 'Brasil' || p.uf === C.state.uf);
  const scopeRecords = () => scopePeople().flatMap(p => C.records(p).filter(r => r.month < state.month).map(r => ({...r,person:p.name,idPerson:p.id})));
  const badge = text => `<span class="p-badge">${text}</span>`;
  const editorial = C.model === 'editorial';
  // Every one of these opens a panel on this page, so the editorial uses a plain arrow, not the external-link mark.
  const ext = () => icon(editorial ? 'arrow' : 'external');
  const motionText = () => editorial ? `Animações ${state.motion?'ligadas':'desligadas'}` : `${state.motion?'◉':'○'} Movimento`;
  const label = (n, text) => editorial ? `<p class="p-kicker">${text}</p>` : `<p class="p-kicker"><span>${n}</span> ${text}</p>`;
  const directTitle = {'Um total. Muitas histórias.':'Gastos por categoria','O Brasil, mais perto.':'Representantes por estado','Lado a lado. Sem atalhos.':'Comparar dois representantes','Ideias em movimento.':'Projetos de lei','Como decidiram?':'Votações · cenário demonstrativo','Um mandato tem muitas dimensões.':'O que ainda não cobrimos','Acompanhe o que muda.':'Acompanhar'};
  const intro = (n, eyebrow, title, description, extra = '') => `<div class="p-section-intro"><div>${label(n,eyebrow)}<h2>${editorial&&directTitle[title]||title}</h2><p class="p-description">${description}</p></div>${extra}</div>`;
  const peopleOptions = selected => C.all().map(p=>`<option value="${p.id}" ${selected===p.id?'selected':''}>${p.name} · ${p.uf}</option>`).join('');
  function followButton(id, full = false) { const on=state.favorites.has(id); return `<button class="follow-button ${on?'is-following':''}" data-p-follow="${id}" aria-pressed="${on}" aria-label="${on?'Deixar de acompanhar':'Acompanhar'} ${C.person(id).name}"><svg class="heart" viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M12 20.5s-7.5-4.6-9.3-9.2C1.4 8 3.4 4.5 6.9 4.5c2.1 0 3.6 1.2 5.1 3 1.5-1.8 3-3 5.1-3 3.5 0 5.5 3.5 4.2 6.8-1.8 4.6-9.3 9.2-9.3 9.2Z"/></svg>${full ? on?'Acompanhando':'Acompanhar':''}</button>`; }
  function scopeText() { return `${C.state.uf==='Brasil'?'Brasil':UF[C.state.uf][0]} · ${C.state.year} · ${C.state.category==='Todas'?'todas as categorias':C.state.category}`; }
  function overview() {
    const people = scopePeople();
    const total = C.sum(people.flatMap(C.records));
    if (editorial) {
      const n=people.length, projects=people.reduce((s,p)=>s+p.projects,0), recs=people.flatMap(C.records).length;
      const stat=(key,value,text,format='number')=>`<button class="p-stat" data-p-summary="${key}"><strong data-counter="${value}" data-format="${format}">${format==='money'?compact(value):number(value)}</strong> ${text}</button>`;
      return `<div class="p-overview-head"><h2 class="p-overview-title">Panorama da amostra</h2><span>${scopeText()}</span></div><p class="p-overview-sentence">Neste recorte, ${stat('people',n,n===1?'deputado':'deputados')} ${n===1?'soma':'somam'} ${stat('expenses',total,'em reembolsos','money')}, distribuídos em ${stat('records',recs,'registros')}, e ${n===1?'apresentou':'apresentaram'} ${stat('projects',projects,'projetos de lei')}.</p>`;
    }
    return `<div class="p-overview-head">${editorial?'<h2 class="p-overview-title">Panorama da amostra</h2>':label('01','Panorama da amostra')}<span>${scopeText()}</span></div><div class="p-stats">${[
      ['Pessoas no recorte',people.length,'perfis para conhecer','people'],
      ['Reembolsos da cota',total,'registros que você pode conferir','expenses'],
      ['Projetos apresentados',people.reduce((n,p)=>n+p.projects,0),'autoria principal · quantidade','projects'],
      ['Registros de despesa',people.flatMap(C.records).length,'disponíveis nesta demonstração','records']
    ].map(([title,value,detail,key])=>`<button class="p-stat" data-p-summary="${key}"><span class="p-stat-label">${title} ${ext()}</span><strong data-counter="${value}" data-format="${key==='expenses'?'money':'number'}">${key==='expenses'?compact(value):number(value)}</strong><span class="p-stat-detail">${detail}</span></button>`).join('')}</div>`;
  }
  function spending() {
    const entries=scopeRecords(), total=C.sum(entries);
    const groups=window.ClareiaData.categories.map((name,i)=>({name,color:editorial?`var(--cat${i+1})`:color[i],value:C.sum(entries.filter(r=>r.category===name))}));
    if(editorial)groups.sort((a,b)=>b.value-a.value);
    // A category excluded by the filter is not zero; say so instead of printing R$ 0.
    const out=g=>editorial&&C.state.category!=='Todas'&&g.name!==C.state.category;
    const highlighted = editorial && groups.some(g=>g.name===state.highlightCategory && !out(g)) ? state.highlightCategory : null;
    let start=0;
    const stops=groups.map(g=>{const end=start+(total?g.value/total*100:0);const s=`${highlighted && highlighted!==g.name ? "var(--line)" : g.color} ${start}% ${end}%`;start=end;return s;}).join(',');
    return `${intro('02','Siga o dinheiro','Um total. Muitas histórias.','Arraste o período e veja de que é feita a conta. Cada categoria leva aos registros que a compõem.',badge('Cota parlamentar'))}
      <div class="spending-grid"><div class="p-panel donut-panel"><div class="donut-caption"><span>Composição das despesas</span><button data-p="spend-evidence" aria-label="Como calculamos as despesas">${editorial?'Como chegamos nisso? →':icon('info')}</button></div><div class="donut-shell"><div class="spend-donut" style="background:${total?'conic-gradient('+stops+')':'var(--line)'}"><div class="donut-hole"><span>Jan–${months[state.month-1]} ${C.state.year}</span><strong>${compact(total)}</strong><small>reembolsos no recorte</small></div></div></div><div class="donut-legend">${groups.map(g=>`<button ${editorial ? `data-p-highlight="${g.name}" aria-pressed="${highlighted===g.name}" ${out(g)?'disabled':''}` : `data-p-category="${g.name}"`} style="--cat:${g.color}" class="${highlighted && highlighted!==g.name?'category-muted':''}"><span><i></i>${g.name}</span>${out(g)?'<strong class="is-out">fora do filtro</strong><small></small>':`<strong>${compact(g.value)}</strong><small>${total?number(g.value/total*100):'0'}%</small>`}</button>`).join('')}</div></div>
      <div class="spend-details"><div class="range-heading"><h3>Explore o ano</h3><output for="spend-range">Jan → ${months[state.month-1]}</output></div><label class="sr-only" for="spend-range">Último mês incluído nas despesas</label><input id="spend-range" class="month-range" type="range" min="1" max="12" value="${state.month}" aria-valuetext="Janeiro a ${months[state.month-1]} de ${C.state.year}"><div class="month-markers"><span>Jan</span><span>Abr</span><span>Jul</span><span>Out</span><span>Dez</span></div>
      <div class="p-mini-bars">${months.map((m,i)=>{const value=C.sum(scopePeople().flatMap(C.records).filter(r=>r.month===i)), max=Math.max(1,...months.map((_,j)=>C.sum(scopePeople().flatMap(C.records).filter(r=>r.month===j))));return `<button data-p-month="${i+1}" class="${i<state.month?'included':''}" aria-label="Incluir até ${m}: ${money(value)} no mês${highlighted?', sendo '+money(C.sum(scopePeople().flatMap(C.records).filter(r=>r.month===i && r.category===highlighted)))+' em '+highlighted:''}"><span style="--height:${Math.max(2,value/max*100)}%;${highlighted?'background:var(--line)':''}">${highlighted?`<i class="category-bar-part" style="height:${value?C.sum(scopePeople().flatMap(C.records).filter(r=>r.month===i && r.category===highlighted))/value*100:0}%;background:${groups.find(g=>g.name===highlighted).color}"></i>`:''}</span><small>${m[0]}</small></button>`;}).join('')}</div>
      ${editorial?`<div class="category-focus" aria-live="polite">${highlighted?`<p><strong>${highlighted}</strong>: ${compact(groups.find(g=>g.name===highlighted).value)} · ${total?number(groups.find(g=>g.name===highlighted).value/total*100):0}% do total de jan–${months[state.month-1]}.</p><p class="p-small">A cor destaca a parcela da categoria. O total e a escala permanecem iguais.</p><button class="p-link" data-p-drill="${highlighted}">Quais fornecedores aparecem nesta categoria? →</button><button class="category-clear" data-p="clear-highlight">Limpar destaque</button>`:'<p class="p-small">Selecione uma categoria na legenda para destacar sua parcela nos meses e nos fornecedores.</p>'}</div>`:''}<div class="category-path"><span>Categoria → fornecedor → registros</span>${groups.map(g=>`<button class="p-link" data-p-drill="${g.name}">Explorar ${g.name} ↗</button>`).join('')}</div><h3 class="supplier-heading">Fornecedores das despesas reembolsadas</h3><p class="p-small">Fornecedores fictícios nos registros selecionados.</p><div class="supplier-list">${groups.map((g,i)=>`<button data-p-category="${g.name}" class="${highlighted && highlighted!==g.name?'category-muted':''}" ${highlighted===g.name?'data-highlighted="true"':''}><span class="supplier-index">0${i+1}</span><span>${['Gráfica Exemplo','Viagens Demonstração','Serviços Modelo'][window.ClareiaData.categories.indexOf(g.name)]}<small>${g.name}</small></span><b>${out(g)?'fora do filtro':compact(g.value)}</b>${ext()}</button>`).join('')}</div><button class="p-link" data-p="spend-evidence">Como chegamos nisso? ${ext()}</button><p class="p-small">${scopeText()} · não inclui salários, gabinete ou emendas.</p></div></div>`;
  }
  // Packed hex grid: c counts half-tile steps so rows interlock; neighbours sit roughly where they are on the map.
  function tileMap() {
    const max=Math.max(1,...Object.keys(UF).map(mapValue).filter(v=>v!==null));
    return `<svg class="uf-map" viewBox="0 0 382 360" role="group" aria-label="Mapa esquemático das 27 unidades federativas, não geográfico">${Object.entries(UF).map(([uf,[name,c,r]])=>{
      const x=10+c*26,y=10+r*41, available=C.all().some(p=>p.uf===uf), value=mapValue(uf);
      return `<g role="button" tabindex="0" data-p-uf="${uf}" aria-label="${name}${available?' — '+mapFormat(value):' — sem dados nesta amostra'}" aria-pressed="${state.mapUF===uf}" class="uf-tile ${available?'has-data':''} ${available&&value/max>.55?'strong':''} ${state.mapUF===uf?'selected':''}" transform="translate(${x} ${y})"><path style="${available?'fill:var(--accent);fill-opacity:'+(.2+.8*value/max):''}" d="M0 12 25 0 50 12 50 40 25 52 0 40Z"/><text x="25" y="31" text-anchor="middle">${uf}</text><title>${name}${available?' · '+mapFormat(value):' · sem dados'}</title></g>`;
    }).join('')}</svg>`;
  }
  function mapValue(uf) {
    const people=C.all().filter(p=>p.uf===uf);
    if(!people.length)return null;
    if(state.mapMetric==='projects')return people.reduce((sum,p)=>sum+p.projects,0);
    const total=C.sum(people.flatMap(C.records));
    return state.mapMetric==='average'?total/people.length:total;
  }
  function mapFormat(value) {return state.mapMetric==='projects'?number(value)+' projetos':money(value);}
  function mapControls() {
    return `<div class="map-metrics"><label>Colorir por<select id="map-metric"><option value="total" ${state.mapMetric==='total'?'selected':''}>Total de reembolsos</option><option value="average" ${state.mapMetric==='average'?'selected':''}>Reembolsos por representante</option><option value="projects" ${state.mapMetric==='projects'?'selected':''}>Projetos apresentados</option></select></label><p class="p-small">Mais intenso = maior valor nesta amostra. Ausência de dados tem preenchimento distinto. ${state.mapMetric==='projects'?'Projetos: autoria principal, sem filtro de despesas.':'Despesas: categoria global selecionada.'} ${C.state.year} · jan–dez.</p><button class="p-link" data-p="map-evidence">Como chegamos nisso? →</button></div>`;
  }
  function linkedChart() {
    const people=[...new Set([state.a,state.b])].map(C.person), start=state.from-1,end=state.to-1;
    const value=(p,i)=>i<p.months?C.sum(C.records(p).filter(r=>r.month===i)):null;
    const max=Math.max(1,...people.flatMap(p=>months.map((_,i)=>value(p,i))).filter(v=>v!==null));
    const x=i=>60+i*70,y=v=>215-v/max*175;
    return `<div class="linked-chart-body"><p class="records-note">${months[start]}–${months[end]} ${C.state.year} · ${C.state.category} · valores mensais absolutos. O recorte abaixo não altera os totais anuais acima.</p><svg class="linked-lines" viewBox="0 0 870 255" role="group" aria-label="Comparação mensal; pontos abrem os registros"><rect x="${x(start)-18}" y="22" width="${x(end)-x(start)+36}" height="196" fill="var(--accent)" opacity=".08"/>${[0,.5,1].map(f=>`<line x1="60" x2="830" y1="${y(max*f)}" y2="${y(max*f)}" stroke="var(--line)"/><text x="62" y="${y(max*f)-6}" text-anchor="start">${compact(max*f)}</text>`).join('')}${people.map((p,j)=>{const vals=months.map((_,i)=>value(p,i)),last=vals.findLastIndex(v=>v!==null);return `<path fill="none" stroke="${color[j]}" stroke-width="3" d="${vals.map((v,i)=>v===null?'':`${i?'L':'M'}${x(i)} ${y(v)}`).join(' ')}"/>${last<0?'':`<text class="line-label" x="${x(last)}" y="${y(vals[last])+(j?22:-12)}" text-anchor="end" style="fill:${color[j]}">${p.name.split(' ')[0]}</text>`}${vals.map((v,i)=>v===null?'':`<circle class="chart-hit" aria-hidden="true" onclick="this.nextElementSibling.dispatchEvent(new MouseEvent('click',{bubbles:true}))" cx="${x(i)}" cy="${y(v)}" r="22" fill="transparent"/><circle class="chart-point" role="button" tabindex="0" data-action="month" data-id="${p.id}" data-month="${i}" cx="${x(i)}" cy="${y(v)}" r="5" fill="${color[j]}" opacity="${i>=start&&i<=end?1:.25}" aria-label="${p.name}, ${months[i]}: ${money(v)}. Abrir registros"><title>${p.name} · ${months[i]} · ${money(v)}</title></circle>`).join('')}`;}).join('')}${months.map((m,i)=>`<text x="${x(i)}" y="242" text-anchor="middle">${m}</text>`).join('')}</svg><div class="linked-totals">${people.map((p,j)=>{const rows=C.records(p).filter(r=>r.month>=start&&r.month<=end);return `<div style="border-color:${color[j]}"><b>${p.name}</b><strong>${money(C.sum(rows))}</strong><small>${rows.length} registros no período selecionado · ${p.months} meses em exercício no ano</small></div>`;}).join('')}</div><details><summary>Ver dados em tabela</summary><div class="table-scroll"><table class="data-table"><thead><tr><th>Mês</th>${people.map(p=>`<th>${p.name}</th>`).join('')}</tr></thead><tbody>${months.slice(start,end+1).map((m,j)=>`<tr><th>${m}</th>${people.map(p=>`<td>${value(p,start+j)===null?'Sem exercício':money(value(p,start+j))}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details><p class="p-small">Clique em um ponto para conferir os registros. Uma variação não prova irregularidade. Sem exercício é diferente de gasto zero.</p></div>`;
  }
  function linkedExplorer() {
    return `<div class="linked-explorer"><h3>O que mudou mês a mês?</h3><p class="p-small">As duas pessoas escolhidas acima alimentam este gráfico.</p><div class="linked-ranges"><label>De <output id="linked-from-label">${months[state.from-1]}</output><input id="linked-from" type="range" min="1" max="12" value="${state.from}" aria-label="Mês inicial da comparação"></label><label>Até <output id="linked-to-label">${months[state.to-1]}</output><input id="linked-to" type="range" min="1" max="12" value="${state.to}" aria-label="Mês final da comparação"></label></div><div id="linked-result">${linkedChart()}</div></div>`;
  }
  function atlasDetail() {
    const ppl=C.all().filter(p=>p.uf===state.mapUF), total=C.sum(ppl.flatMap(C.records));
    return `<p class="p-kicker">${state.mapUF} / ${UF[state.mapUF][0]}</p><h3>${ppl.length?'Conheça quem está no seu recorte.':'Ainda não há dados nesta amostra.'}</h3><p class="p-small">A UF indica o estado de representação. Não é o local onde a despesa ocorreu.</p>
      ${ppl.length?`<div class="atlas-numbers"><div><strong>${ppl.length}</strong><span>perfis fictícios</span></div><div><strong>${mapFormat(mapValue(state.mapUF))}</strong><span>${state.mapMetric==='projects'?'projetos apresentados':state.mapMetric==='average'?'cota por representante':'cota total'} · ${C.state.year}${editorial&&state.mapMetric!=='projects'?' · valor exato':''}</span></div></div><div class="atlas-people">${ppl.map(p=>`<div>${C.avatar(p)}<button data-action="profile" data-id="${p.id}"><b>${p.name}</b><small>Deputado(a) federal · ${p.uf}</small></button>${followButton(p.id)}</div>`).join('')}</div><button class="p-primary" data-p="apply-state">Explorar ${UF[state.mapUF][0]} ${icon('arrow')}</button>`:`<div class="map-empty">${icon('database')}<p>Indisponível não significa zero.</p><span>Experimente São Paulo, Minas Gerais ou Rio de Janeiro.</span></div><button class="p-primary" data-p-uf="SP">${editorial?'Ver um estado com amostra':'Explorar São Paulo'} ${icon('arrow')}</button>`}`;
  }
  function atlas() {
    return `${intro('03','Atlas de representantes','O Brasil, mais perto.','Escolha um estado. Descubra as pessoas por trás dos números e leve o recorte para o restante da página.',badge('27 UFs · 3 com amostra'))}<div class="atlas-grid"><div class="map-canvas"><div class="map-topline"><span>BRASIL / UNIDADES FEDERATIVAS</span><button data-p="map-reset">Visão inicial ↺</button></div>${mapControls()}${tileMap()}<div class="map-key"><span><i class="filled"></i>Com amostra</span><span><i></i>Sem dados</span></div><p class="p-small">Mapa esquemático por UF, não geográfico.</p><label class="map-select">Escolher estado<select id="map-select">${Object.entries(UF).sort((a,b)=>a[1][0].localeCompare(b[1][0],'pt-BR')).map(([uf,[name]])=>`<option value="${uf}" ${state.mapUF===uf?'selected':''}>${name}</option>`).join('')}</select></label></div><div class="atlas-detail" id="atlas-detail" aria-live="polite">${atlasDetail()}</div></div>`;
  }
  function comparison() {
    const a=C.person(state.a),b=C.person(state.b), get=p=>C.sum(C.records(p))/(C.state.metric==='mensal'?p.months:1), av=get(a),bv=get(b),delta=bv?(av-bv)/bv*100:0;
    return `${intro('04','Comparação com contexto','Lado a lado. Sem atalhos.','Escolha duas pessoas e compare a mesma métrica, no mesmo período. Abra as evidências antes de tirar conclusões.')}
      <div class="compare-controls"><label>Primeiro representante<select id="compare-a">${peopleOptions(state.a)}</select></label><button class="swap-button" data-p="swap" aria-label="Inverter representantes">⇄</button><label>Segundo representante<select id="compare-b">${peopleOptions(state.b)}</select></label><div class="p-metric" role="group" aria-label="Comparação total ou por mês"><button data-p-metric="total" aria-pressed="${C.state.metric==='total'}">Total</button><button data-p-metric="mensal" aria-pressed="${C.state.metric==='mensal'}">Por mês</button></div></div>
      <div class="comparison-board"><div class="compare-person">${C.avatar(a)}<div><p>${a.uf} · ${a.months} meses em exercício</p><h3>${a.name}</h3>${followButton(a.id,true)}</div><button data-action="evidence" data-id="${a.id}" data-kind="gastos" class="compare-total">${compact(av)} →</button></div><div class="comparison-center"><span class="vs">×</span><strong>${number(Math.abs(delta))}%</strong><p>${av===bv?'Valores iguais':`${delta>0?'a mais':'a menos'} para ${a.name.split(' ')[0]} do que para ${b.name.split(' ')[0]}`}</p>${editorial&&a.months!==b.months&&C.state.metric!=='mensal'?`<p class="tenure-note">Meses em exercício diferentes (${a.months} × ${b.months}). Compare por mês.</p>`:''}<button data-p="compare-evidence">Como chegamos nisso? →</button></div><div class="compare-person second">${C.avatar(b)}<div><p>${b.uf} · ${b.months} meses em exercício</p><h3>${b.name}</h3>${followButton(b.id,true)}</div><button data-action="evidence" data-id="${b.id}" data-kind="gastos" class="compare-total">${compact(bv)} →</button></div></div>
      <div class="compare-breakdown">${(()=>{const cats=window.ClareiaData.categories,val=(p,cat)=>C.sum(C.records(p).filter(r=>r.category===cat))/(C.state.metric==='mensal'?p.months:1),max=Math.max(1,...cats.flatMap(cat=>[val(a,cat),val(b,cat)]));return cats.map(cat=>{const x=val(a,cat),y=val(b,cat);return `<div class="compare-category"><span>${compact(x)}</span><div class="left-bar"><i style="width:${x/max*100}%"></i></div><b>${cat}</b><div class="right-bar"><i style="width:${y/max*100}%"></i></div><span>${compact(y)}</span></div>`;}).join('')})()}</div><div class="compare-foot"><p>${C.state.year} · ${C.state.category==='Todas'?'todas as categorias':C.state.category} · ${C.state.metric==='mensal'?'média por mês em exercício':'total de reembolsos'}${a.months!==b.months?' · tempos em exercício diferentes':''}</p><button class="p-link" data-p="ask-comparison">Investigar esta comparação ${icon('arrow')}</button></div>${linkedExplorer()}`;
  }
  function directoryCards() {
    const normalize=s=>s.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    const ppl=C.all().filter(p=>normalize(p.name).includes(normalize(state.rosterQuery))&&(state.rosterUF==='Todos'||p.uf===state.rosterUF)&&(state.rosterParty==='Todos'||parties[p.id]===state.rosterParty));
    const head=editorial&&ppl.length?`<div class="directory-head" aria-hidden="true"><span>Representante</span><span>Cota ${C.state.metric==='mensal'?'por mês':'no recorte'}</span><span>Projetos${C.state.metric==='mensal'?' por mês':''}</span><span></span></div>`:'';
    return ppl.length?head+ppl.map(p=>`<article class="directory-card"><div class="directory-person">${C.avatar(p)}<div><h3>${p.name}</h3><p>${p.uf} · partido fictício ${parties[p.id]}</p></div>${followButton(p.id)}</div><div class="directory-stats"><button data-action="evidence" data-id="${p.id}" data-kind="gastos"><b>${compact(C.sum(C.records(p))/(C.state.metric==='mensal'?p.months:1))}</b><small>cota ${C.state.metric==='mensal'?'por mês':'no recorte'}</small></button><button data-action="evidence" data-id="${p.id}" data-kind="projetos"><b>${number(p.projects/(C.state.metric==='mensal'?p.months:1))}</b><small>projetos ${C.state.metric==='mensal'?'por mês':'apresentados'}</small></button></div><div class="directory-actions"><button data-action="profile" data-id="${p.id}">Abrir perfil →</button><button data-p-add-compare="${p.id}">Comparar +</button></div></article>`).join(''):'<div class="empty-state"><b>Nenhum perfil encontrado.</b><p>Os filtros consultam apenas os cinco nomes fictícios da amostra.</p><button class="outline-button" data-p="clear-directory">Limpar filtros</button></div>';
  }
  function directory() {
    return `<div class="directory-heading"><h3>Encontre um representante</h3><span>5 perfis · partidos fictícios PA, PB e PC</span></div><div class="directory-controls"><label><span class="sr-only">Nome do representante</span><input id="roster-query" placeholder="Buscar por nome" value="${esc(state.rosterQuery)}"></label><label><span class="sr-only">Estado do representante</span><select id="roster-uf">${['Todos','SP','MG','RJ'].map(v=>`<option value="${v}" ${state.rosterUF===v?'selected':''}>${v==='Todos'?'Todos os estados':v}</option>`).join('')}</select></label><label><span class="sr-only">Partido fictício</span><select id="roster-party">${['Todos','PA','PB','PC'].map(v=>`<option value="${v}" ${state.rosterParty===v?'selected':''}>${v==='Todos'?'Todos os partidos':'Partido fictício '+v}</option>`).join('')}</select></label></div><div class="directory-grid" id="directory-grid" aria-live="polite">${directoryCards()}</div>`;
  }
  function projectCards() {
    const filtered=projects.filter(p=>(state.topic==='Todos'||p.topic===state.topic)&&(state.stage==='Todos'||p.stage===state.stage)&&`${p.title} ${C.person(p.author).name}`.toLocaleLowerCase('pt-BR').includes(state.projectQuery.toLocaleLowerCase('pt-BR')));
    return filtered.length?filtered.map((p,i)=>`<article class="project-card p-reveal" style="--stagger:${i*65}ms"><div class="project-top"><span>DEMO ${p.id} / ${C.state.year}</span><button class="project-save" data-p-project-save="${p.id}" aria-label="${state.projects.has(p.id)?'Deixar de acompanhar':'Acompanhar'} projeto DEMO ${p.id}" aria-pressed="${state.projects.has(p.id)}">${state.projects.has(p.id)?'✓':'+'}</button></div><span class="project-topic">${p.topic}</span><button class="project-title" data-p-project="${p.id}"><h3>${p.title}</h3></button><div class="project-author">${C.avatar(C.person(p.author))}<span>${C.person(p.author).name}<small>Autoria principal</small></span></div><div class="project-progress" aria-label="Etapa ${p.step+1} de 5">${p.trail.map((_,j)=>`<i class="${j<=p.step?'done':''}"></i>`).join('')}</div><div class="project-bottom"><span>${p.stage}</span><button data-p-project="${p.id}" aria-label="Abrir projeto DEMO ${p.id}">${ext()}</button></div></article>`).join(''):`<div class="empty-state"><b>Nenhum projeto nesse recorte.</b><p>Tente outro tema, etapa ou termo.</p><button class="outline-button" data-p="clear-projects">Limpar filtros</button></div>`;
  }
  function projectSection() {
    return `${intro('05','Além da quantidade','Ideias em movimento.','Apresentar um projeto é só o começo. Explore a proposta, a autoria e cada etapa do caminho.',badge('4 projetos ilustrativos'))}<div class="project-filters"><div class="topic-tabs" role="group" aria-label="Tema dos projetos">${['Todos','Transparência','Educação','Acessibilidade','Meio ambiente'].map(t=>`<button data-p-topic="${t}" aria-pressed="${state.topic===t}">${t}</button>`).join('')}</div><div class="project-search"><label class="sr-only" for="project-search">Buscar projeto ou autor</label><input id="project-search" placeholder="Buscar projeto ou autor" value="${esc(state.projectQuery)}"><label class="sr-only" for="project-stage">Etapa do projeto</label><select id="project-stage">${['Todos','Em análise','Em votação','Aprovado na Câmara'].map(s=>`<option ${state.stage===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="project-grid" id="project-grid" aria-live="polite">${projectCards()}</div><p class="p-small section-endnote">Seleção ilustrativa, não a lista completa usada nas contagens dos rankings. Nenhum destes identificadores corresponde a um projeto real.</p>`;
  }
  function voteCards() {
    return votes.map((v,i)=>{const counts=Object.values(v.choices).reduce((a,c)=>(a[c]=(a[c]||0)+1,a),{});return `<article class="vote-card p-reveal"><div class="vote-card-head"><span>VOTAÇÃO DEMO 0${i+1}</span><span>Universo: 5 perfis</span></div><h3>${v.title}</h3><p>${v.desc}</p><div class="vote-stackbar" role="img" aria-label="${Object.entries(counts).map(([k,n])=>`${n} ${k}`).join(', ')}">${['Sim','Não','Abstenção','Ausente'].map(choice=>`<span class="vote-${choice==='Sim'?'yes':choice==='Não'?'no':choice==='Abstenção'?'abstain':'absent'}" style="width:${(counts[choice]||0)*20}%"></span>`).join('')}</div><div class="vote-tally">${['Sim','Não','Abstenção','Ausente'].map(c=>`<span>${c}<b>${counts[c]||0}</b></span>`).join('')}</div><div class="your-vote">${C.avatar(C.person(state.voter))}<span>${C.person(state.voter).name}<small>Nesta votação fictícia</small></span><strong>${v.choices[state.voter]}</strong></div><button class="p-link" data-p-vote="${v.id}">Entender a votação ${ext()}</button></article>`;}).join('');
  }
  function voteSection() {
    return `${intro('06','O voto e seu contexto','Como decidiram?', 'O objeto da votação vem antes do placar. Veja a etapa, o texto em discussão e a participação de cada pessoa.')}<div class="voter-control"><label for="voter">Destaque um representante</label><select id="voter">${peopleOptions(state.voter)}</select><span>Um voto não é nota de qualidade.</span></div><div class="vote-grid" id="vote-grid">${voteCards()}</div>`;
  }
  function moreSection() {
    return `${intro('07','Conecte as peças','Um mandato tem muitas dimensões.','Explore outras camadas do perfil. Nesta versão, os cenários abaixo também são demonstrativos.')}
      <div class="dossier-grid">${[
        ['trajectory','01','Trajetória e eleições','Do registro de candidatura ao exercício do mandato.','Candidatura → mandato'],
        ['assets','02','Patrimônio declarado','O que foi declarado, em qual eleição e em que data.','Declaração ≠ patrimônio atual'],
        ['amendments','03','Emendas e municípios','Separe o valor indicado, empenhado e efetivamente pago.','Indicado → empenhado → pago'],
        ['suppliers','04','Fornecedores','Explore quem aparece nos registros e como o total se distribui.','Registro → categoria → fornecedor']
      ].filter(([key])=>!editorial||key!=='suppliers').map(([key,n,title,desc,foot])=>`<button class="dossier-card p-reveal" data-p-dossier="${key}"><span class="dossier-num">${n}</span><span class="dossier-tag">Cenário demonstrativo</span><h3>${title}</h3><p>${desc}</p><span class="dossier-foot">${foot}${ext()}</span></button>`).join('')}</div>`;
  }
  function events(id) { const p=C.person(id); return [
    {date:`15 OUT ${C.state.year}`,title:'Novo registro de atividade',text:`${p.name} aparece no cenário de votação demonstrativa.`,action:'vote',value:'v1'},
    {date:`19 AGO ${C.state.year}`,title:'Uma proposta avançou',text:'Veja o que muda entre uma etapa de tramitação e uma lei em vigor.',action:'project',value:projects.find(pr=>pr.author===id)?.id||'03'},
    {date:`15 MAR ${C.state.year}`,title:'Despesas disponíveis para consulta',text:'Abra o detalhamento por categoria e os registros do período.',action:'records',value:id},
    {date:`01 JAN ${C.state.year}`,title:'O recorte começa aqui',text:`Perfil fictício · ${p.uf} · ${p.months} meses em exercício nesta amostra.`,action:'profile',value:id}
  ]; }
  function timeline() {return events(state.timeline).map((e,i)=>`<button class="timeline-event p-reveal" data-p-event="${e.action}" data-value="${e.value}"><span class="timeline-dot"></span><time>${e.date}</time><div><h3>${e.title}</h3><p>${e.text}</p></div>${ext()}</button>`).join('');}
  function savedList() {
    return state.favorites.size?`<div class="saved-people">${[...state.favorites].map(id=>{const p=C.person(id);return `<div>${C.avatar(p)}<button data-action="profile" data-id="${id}"><b>${p.name}</b><small>${p.uf} · abrir perfil</small></button>${followButton(id)}</div>`;}).join('')}</div>`:`<div class="saved-empty"><span class="saved-orbit" aria-hidden="true">+</span><h3>Comece por uma pessoa.</h3><p>Salve um perfil e volte para explorar sua atividade.</p><button class="p-primary" data-p-follow="ana">Acompanhar Ana Martins +</button></div>`;
  }
  function following() {
    return `${intro('08','A política continua','Acompanhe o que muda.','Construa sua própria lista de acompanhamento. Os favoritos ficam salvos apenas neste navegador.')}<div class="following-grid"><div class="timeline-panel"><div class="timeline-heading"><h3>Linha do tempo do mandato</h3><label class="sr-only" for="timeline-person">Pessoa da linha do tempo</label><select id="timeline-person">${peopleOptions(state.timeline)}</select></div><div class="timeline">${timeline()}</div><p class="p-small">Eventos ilustrativos; não são atualizações em tempo real.</p></div><aside class="saved-panel"><div class="saved-heading"><h3>Meu acompanhamento</h3><span>${state.favorites.size}</span></div><div id="saved-list">${savedList()}</div><div class="saved-projects"><span>Projetos acompanhados</span><b>${state.projects.size}</b>${state.projects.size?`<div>${[...state.projects].map(id=>`<button data-p-project="${id}">DEMO ${id} ↗</button>`).join('')}</div>`:''}</div><button class="outline-button weekly-button" data-p="brief" ${!state.favorites.size?'disabled':''}>Abrir resumo dos acompanhados ${icon('arrow')}</button><p class="p-small">Sem cadastro. Nenhum e-mail ou alerta externo é enviado.</p></aside></div>`;
  }
  function closing() {
    return `<div class="closing-top">${label('09','A sua próxima pergunta')}<h2>Curiosidade é <br>um bom começo.</h2><p>Você não precisa conhecer a API ou o vocabulário do Congresso. <br>Comece com uma pergunta. Termine nos registros.</p><div class="closing-questions">${['Quem mais gastou por mês?','Compare Ana e Carla','Quem apresentou mais projetos?'].map(q=>`<button data-question="${q}">${q}${icon('arrow')}</button>`).join('')}</div></div><div class="trust-row"><div><span>01</span><h3>Fonte à vista</h3><p>Cada número tem um caminho até os registros.</p></div><div><span>02</span><h3>Contexto primeiro</h3><p>Período, cobertura e definição acompanham a comparação.</p></div><div><span>03</span><h3>Limites explícitos</h3><p>Ausência de dados nunca vira zero ou uma resposta inventada.</p></div></div><button class="p-link" data-action="methodology">Conheça a metodologia ${ext()}</button>`;
  }
  const sections = [['panorama',overview],['despesas',spending],['atlas',atlas],['pessoas',directory],['comparacao',comparison],['projetos',projectSection],['votacoes',voteSection],['dimensoes',moreSection],['acompanhar',following],['perguntar',closing]];
  function mount() {
    const main=$('#main');
    main.insertAdjacentHTML('afterbegin',`<div class="page-progress" aria-hidden="true"><i></i></div><nav class="section-dock" aria-label="Seções da página"><a href="#rankings">Rankings</a><a href="#despesas">${editorial?'Gastos':'Despesas'}</a><a href="#atlas">Mapa</a>${editorial?'':'<a href="#comparacao">Comparar</a>'}<a href="#projetos">Projetos</a><a href="#votacoes">Votações</a><a href="#acompanhar">Acompanhar <span id="saved-count">${state.favorites.size||''}</span></a><button class="motion-toggle" data-p="motion" aria-pressed="${state.motion}" aria-label="Ativar ou desativar animações">${motionText()}</button></nav>`);
    main.insertAdjacentHTML('beforeend',`<div class="full-portal">${sections.map(([id,render])=>`<section class="p-section" id="${id}">${render()}</section>`).join('')}</div>`);
    $('.footer').innerHTML=`<div class="footer-brand"><span class="logo">clareia<svg class="brand-rays" viewBox="0 0 25 30" aria-hidden="true"><path d="M5 8 8 3M10 13l8-3M11 19l9 2M6 23l4 5"/></svg></span><p>Entenda. Confira. Acompanhe.</p></div><div class="footer-links"><a href="#atlas">Explorar por estado</a><a href="#projetos">Projetos e propostas</a><button data-action="methodology">Fontes e metodologia</button><button data-p="coverage">Cobertura da amostra</button><button data-p="reset-saved">Apagar favoritos locais</button></div><div class="footer-disclaimer"><span>Conceito interativo · ${new Date().getFullYear()}</span><p>Pessoas, retratos, registros e atividades fictícios. Busca demonstrativa sem IA conectada. Não há integração de dados oficiais.</p><button data-p="top">Voltar ao topo ↑</button></div>`;
    document.body.insertAdjacentHTML('beforeend',`<button class="assistant-launcher" data-p="assistant" aria-label="${editorial?'Fazer uma pergunta na busca':'Abrir assistente de investigação'}"><span class="assistant-spark" aria-hidden="true">✳</span><span>${editorial?'Fazer uma pergunta':'Pergunte ao Clareia'}</span>${icon('arrow')}</button>`);
    document.body.dataset.motion=state.motion?'on':'off';
    watchMotion(); watchSections();
  }
  let observer;
  function watchMotion() {
    observer?.disconnect();
    document.querySelectorAll('.p-section-intro,.p-panel,.p-stat,.dossier-card,.project-card,.vote-card,.timeline-event').forEach(el=>el.classList.add('p-reveal'));
    if (!state.motion) { document.querySelectorAll('.p-reveal').forEach(el=>el.classList.add('is-visible')); return; }
    observer=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>{if(isIntersecting){target.classList.add('is-visible');if(target.matches('.p-stat'))animateCounter(target);observer.unobserve(target);}}),{threshold:.08});
    document.querySelectorAll('.p-reveal:not(.is-visible)').forEach(el=>observer.observe(el));
  }
  function animateCounter(el) { const target=el.querySelector('[data-counter]');if(!target)return;const value=+target.dataset.counter,start=performance.now();function frame(now){if(!target.isConnected)return;const t=Math.min(1,(now-start)/700),n=Math.round(value*(1-Math.pow(1-t,3)));target.textContent=target.dataset.format==='money'?compact(n):number(n);if(t<1&&state.motion)requestAnimationFrame(frame);else target.textContent=target.dataset.format==='money'?compact(value):number(value);}requestAnimationFrame(frame); }
  // Position-based spy: the current section is the last one whose top has passed 35% of the viewport; none above the first.
  function spySections() {
    const line=innerHeight*.35; let cur=null;
    document.querySelectorAll('#rankings,.p-section').forEach(el=>{if(el.getBoundingClientRect().top<=line)cur=el.id;});
    document.querySelectorAll('.section-dock a').forEach(a=>{const on=a.hash==='#'+cur;a.classList.toggle('current',on);if(on)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});
  }
  function watchSections() { spySections(); }
  function renderPart(id,render) { const el=$('#'+id); if(el)el.innerHTML=render(); }
  function updateSpending() {
    // Keep the actual range input mounted so dragging retains pointer capture.
    const temp=document.createElement('div');temp.innerHTML=spending();
    for(const selector of ['.donut-panel','.p-mini-bars','.supplier-list', ...(editorial?['.category-focus']:[])]) $('#despesas '+selector).innerHTML=temp.querySelector(selector).innerHTML;
    $('#despesas output').textContent=`Jan → ${months[state.month-1]}`;
    $('#spend-range').setAttribute('aria-valuetext',`Janeiro a ${months[state.month-1]} de ${C.state.year}`);
  }
  function updateAll() { sections.forEach(([id,render])=>renderPart(id,render));watchMotion(); }
  function updateSaved() { renderPart('acompanhar',following);$('#saved-count').textContent=state.favorites.size||'';document.querySelectorAll('[data-p-follow]').forEach(b=>{const on=state.favorites.has(b.dataset.pFollow);b.setAttribute('aria-pressed',on);b.classList.toggle('is-following',on);if(b.classList.contains('follow-button')){const full=b.textContent.trim().length>2;b.innerHTML=`<svg class="heart" viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M12 20.5s-7.5-4.6-9.3-9.2C1.4 8 3.4 4.5 6.9 4.5c2.1 0 3.6 1.2 5.1 3 1.5-1.8 3-3 5.1-3 3.5 0 5.5 3.5 4.2 6.8-1.8 4.6-9.3 9.2-9.3 9.2Z"/></svg>${full?on?'Acompanhando':'Acompanhar':''}`;b.setAttribute('aria-label',`${on?'Deixar de acompanhar':'Acompanhar'} ${C.person(b.dataset.pFollow).name}`);}});watchMotion(); }
  function focusMatch(selector) { $(selector)?.focus({preventScroll:true}); }
  function expenseEvidence(category, supplier) {
    const items=scopeRecords().filter(r=>(!category||r.category===category)&&(!supplier||r.supplier===supplier)), total=C.sum(items);
    C.showDialog(category||'Como chegamos nisso?',`<p class="dialog-subtitle">Despesas da amostra, registro por registro.</p><p class="records-note">${scopeText()} · Jan–${months[state.month-1]}${category?' · '+category:''}</p><div class="calculation-result">${money(total)}<small>Soma de ${items.length} registros fictícios</small></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Pessoa / mês</th><th>Categoria</th><th>Valor</th></tr></thead><tbody>${items.map(r=>`<tr><td>${r.person}<br><small>${months[r.month]} · ${r.id}</small></td><td>${r.category}</td><td>${money(r.amount)}</td></tr>`).join('')}</tbody><tfoot><tr><th colspan="2">Total conferido</th><td>${money(total)}</td></tr></tfoot></table></div><p class="fixture-note">Todos os registros são fictícios. Salários, gabinete e emendas não entram nesta soma.</p>`);
  }
  function supplierDetail(category) {
    const rows=scopeRecords().filter(r=>r.category===category);
    const names=[...new Set(rows.map(r=>r.supplier))];
    C.showDialog('Da categoria ao fornecedor',`<p class="records-note">${category} · ${scopeText()} · Jan–${months[state.month-1]}</p><div class="calculation-result">${money(C.sum(rows))}<small>Soma dos registros da categoria selecionada</small></div><div class="supplier-list">${names.map(name=>`<button data-p-supplier="${esc(name)}" data-category="${category}"><span>${esc(name)}<small>${rows.filter(r=>r.supplier===name).length} registros fictícios</small></span><b>${money(C.sum(rows.filter(r=>r.supplier===name)))}</b>↗</button>`).join('')||'<p>Sem registros neste recorte.</p>'}</div><p class="fixture-note">Clique no fornecedor para abrir os registros. Na produção, o vínculo dependerá do identificador oficial; nomes parecidos não bastam.</p>`);
  }
  function projectDetail(id) {
    const p=projects.find(p=>p.id===id);if(!p)return;
    C.showDialog('O caminho da proposta',`<p class="p-kicker">PROJETO DEMO ${p.id} / ${C.state.year} · ${p.topic}</p><h3 class="detail-project-title">${p.title}</h3><p class="text-content">${p.summary}</p><div class="detail-project-author">${C.avatar(C.person(p.author))}<div><b>${C.person(p.author).name}</b><p>Autoria principal · ${p.date}</p></div></div><div class="project-detail-trail">${p.trail.map((t,i)=>`<div class="${i<=p.step?'complete':''}"><span>${i<p.step?'✓':String(i+1).padStart(2,'0')}</span><div><b>${t}</b><small>${i===p.step?'Etapa atual do cenário':i<p.step?'Etapa concluída no cenário':'Ainda não ocorreu no cenário'}</small></div></div>`).join('')}</div><button class="p-primary" data-p-project-save="${id}" aria-pressed="${state.projects.has(id)}">${state.projects.has(id)?'✓ Acompanhando projeto':'+ Acompanhar projeto'}</button><p class="fixture-note">Proposta e tramitação inteiramente fictícias. Aprovado na Câmara não significa transformado em lei. Nenhuma fonte externa sustenta este cenário.</p>`);
  }
  function voteDetail(id) {
    const v=votes.find(v=>v.id===id);if(!v)return;
    C.showDialog('Entenda esta votação',`<p class="p-kicker">CENÁRIO FICTÍCIO · ${C.state.year}</p><h3 class="detail-project-title">${v.title}</h3><p class="text-content">${v.desc} Os cinco perfis formam todo o universo desta demonstração; não representam o plenário real.</p><div class="vote-rollcall">${C.all().map(p=>`<div>${C.avatar(p)}<button data-action="profile" data-id="${p.id}">${p.name}</button><strong>${v.choices[p.id]}</strong></div>`).join('')}</div><button class="p-link" data-p-project="${v.project}">Ver a proposta relacionada ${icon('arrow')}</button><p class="fixture-note">Placar, pessoas e votos fictícios. Ausência e abstenção são situações distintas. Esta seleção de três votações não é a contagem anual do ranking.</p>`);
  }
  function dossier(key) {
    const p=C.person(state.timeline);
    const header=`<p class="dialog-subtitle">${p.name} · cenário ilustrativo</p>`;
    const note='<p class="fixture-note">Todos os valores e eventos deste painel são fictícios. Esta interface demonstra uma expansão futura; ainda não há integração com TSE, Senado ou Portal da Transparência.</p>';
    if(key==='trajectory') C.showDialog('Trajetória e eleições',header+`<div class="text-content"><h3>Candidatura de demonstração</h3><p>Deputado(a) federal · ${p.uf} · partido fictício PA.</p><div class="profile-stat"><span>Votos no cenário eleitoral</span><strong>84.320</strong></div><h3>Histórico do cenário</h3><p><b>2022</b> — registro de candidatura e declaração de bens.</p><p><b>2023</b> — início do mandato fictício.</p><p><b>${C.state.year}</b> — ${p.months} meses em exercício no recorte demonstrativo.</p><h3>Como os dados seriam ligados</h3><p>Identificadores oficiais conectariam candidatura, pessoa e mandato. Nomes iguais, sozinhos, não bastam.</p></div>`+note);
    else if(key==='assets') C.showDialog('Patrimônio declarado',header+`<p class="records-note">Cenário de declaração eleitoral de 2022. Não representa patrimônio atual.</p><div class="calculation-result">R$ 580 mil<small>Soma dos três bens declarados no cenário</small></div><table class="data-table"><thead><tr><th>Categoria fictícia</th><th>Valor declarado</th></tr></thead><tbody><tr><td>Imóvel</td><td>R$ 420.000</td></tr><tr><td>Veículo</td><td>R$ 80.000</td></tr><tr><td>Aplicações</td><td>R$ 80.000</td></tr></tbody></table><p class="text-content">Valor declarado não é avaliação de mercado nem comprovação de enriquecimento. Data e eleição acompanham a informação.</p>`+note);
    else if(key==='amendments') C.showDialog('Emendas e municípios',header+`<p class="records-note">A indicação, o empenho e o pagamento são etapas diferentes.</p><div class="amendment-path"><div><small>Indicado</small><strong>R$ 1 mi</strong></div><span>→</span><div><small>Empenhado</small><strong>R$ 800 mil</strong></div><span>→</span><div><small>Pago</small><strong>R$ 450 mil</strong></div></div><table class="data-table"><thead><tr><th>Destino do cenário</th><th>Indicado</th><th>Pago</th></tr></thead><tbody><tr><td>Município Alfa · Saúde</td><td>R$ 600.000</td><td>R$ 300.000</td></tr><tr><td>Município Beta · Educação</td><td>R$ 400.000</td><td>R$ 150.000</td></tr></tbody></table><h3 class="detail-subheading">O que o pagamento não prova</h3><p class="text-content">O valor pago não comprova sozinho que uma obra foi concluída ou que o serviço foi entregue.</p>`+note);
    else expenseEvidence();
  }
  function summary(key) {
    if(key==='expenses'||key==='records'){const before=state.month;state.month=12;expenseEvidence();state.month=before;return;}
    const ppl=scopePeople();
    C.showDialog('Como chegamos nisso?',`<p class="records-note">${scopeText()} · ${key==='people'?'contagem dos perfis':'soma de projetos de autoria principal'}</p><table class="data-table"><thead><tr><th>Representante fictício</th><th>${key==='people'?'UF':'Projetos'}</th></tr></thead><tbody>${ppl.map(p=>`<tr><td>${p.name}</td><td>${key==='people'?p.uf:p.projects}</td></tr>`).join('')}</tbody><tfoot><tr><th>Total</th><td>${key==='people'?ppl.length:ppl.reduce((n,p)=>n+p.projects,0)}</td></tr></tfoot></table><p class="fixture-note">Não há avaliação de qualidade do mandato. Estes são dados fictícios.</p>`);
  }
  function brief() {C.showDialog('Seu resumo de acompanhamento',`<p class="records-note">Seleção local · cenários de ${C.state.year}. Nenhuma notificação foi enviada.</p>${[...state.favorites].map(id=>`<section class="brief-person"><h3>${C.person(id).name}</h3>${events(id).slice(0,2).map(e=>`<button data-p-event="${e.action}" data-value="${e.value}"><small>${e.date}</small><b>${e.title}</b><span>${e.text} ↗</span></button>`).join('')}</section>`).join('')||'<p>Acompanhe uma pessoa para montar seu resumo.</p>'}`);}
  function assistant() {C.showDialog('Sua investigação começa aqui',`<div class="assistant-intro"><span class="assistant-spark">✳</span><h3>Qual número você quer entender?</h3><p>Escolha uma pergunta ou escreva a sua. A demonstração consulta os registros locais, sem IA conectada.</p></div><form id="assistant-form"><label class="sr-only" for="assistant-query">Sua pergunta</label><textarea id="assistant-query" placeholder="Ex.: Ana gastou mais que Bruno?" maxlength="300" required></textarea><button class="p-primary" type="submit">Investigar ${icon('arrow')}</button></form><div class="assistant-examples">${['Compare Ana e Carla','Quem de MG mais gastou com passagens?','Quem apresentou mais projetos?'].map(q=>`<button data-p-ask="${q}">${q}${icon('arrow')}</button>`).join('')}</div><p class="p-small">Cobertura: cinco perfis fictícios, gastos e projetos de 2024 e 2025.</p>`);setTimeout(()=>$('#assistant-query')?.focus(),30);}
  function runAsk(q) {C.closeDialog();C.ask(q);$('#answer-slot').scrollIntoView({behavior:state.motion?'smooth':'instant',block:'center'});}
  document.addEventListener('clareia:change',updateAll);
  document.addEventListener('click',e=>{
    const b=e.target.closest('[data-p-highlight],[data-p],[data-p-follow],[data-p-uf],[data-p-category],[data-p-supplier],[data-p-drill],[data-p-month],[data-p-metric],[data-p-topic],[data-p-project],[data-p-project-save],[data-p-vote],[data-p-dossier],[data-p-event],[data-p-summary],[data-p-ask],[data-p-add-compare]');if(!b)return;
    if(b.dataset.pHighlight){state.highlightCategory=state.highlightCategory===b.dataset.pHighlight?null:b.dataset.pHighlight;updateSpending();focusMatch(`[data-p-highlight="${b.dataset.pHighlight}"]`);return;}
    if(b.dataset.pSupplier){expenseEvidence(b.dataset.category,b.dataset.pSupplier);return;}
    if(b.dataset.pDrill){supplierDetail(b.dataset.pDrill);return;}
    if(b.dataset.pAddCompare){state.a=b.dataset.pAddCompare;if(state.b===state.a)state.b=state.a==='ana'?'bruno':'ana';renderPart('comparacao',comparison);if(editorial){C.toast(`${C.person(state.a).name.split(' ')[0]} entrou na comparação, ao lado de ${C.person(state.b).name.split(' ')[0]}.`);const h=$('#comparacao h2');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}}$('#comparacao').scrollIntoView({behavior:state.motion?'smooth':'instant',block:'start'});return;}
    if(b.dataset.pFollow){const id=b.dataset.pFollow;state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);save('clareia-favorites',[...state.favorites]);updateSaved();focusMatch(`[data-p-follow="${id}"]`);C.toast(state.favorites.has(id)?'Perfil salvo neste navegador.':'Perfil removido do acompanhamento.');return;}
    if(b.dataset.pUf){state.mapUF=b.dataset.pUf;renderPart('atlas',atlas);focusMatch(`[data-p-uf="${state.mapUF}"]`);return;}
    if(b.dataset.pCategory){expenseEvidence(b.dataset.pCategory);return;}
    if(b.dataset.pMonth){state.month=+b.dataset.pMonth;renderPart('despesas',spending);focusMatch(`[data-p-month="${state.month}"]`);return;}
    if(b.dataset.pMetric){C.state.metric=b.dataset.pMetric;C.refresh();focusMatch(`[data-p-metric="${C.state.metric}"]`);return;}
    if(b.dataset.pTopic){state.topic=b.dataset.pTopic;renderPart('projetos',projectSection);watchMotion();focusMatch(`[data-p-topic="${state.topic}"]`);return;}
    if(b.dataset.pProject){projectDetail(b.dataset.pProject);return;}
    if(b.dataset.pProjectSave){const id=b.dataset.pProjectSave;state.projects.has(id)?state.projects.delete(id):state.projects.add(id);save('clareia-projects',[...state.projects]);renderPart('project-grid',projectCards);updateSaved();if($('#detail').open)projectDetail(id);focusMatch(`[data-p-project-save="${id}"]`);return;}
    if(b.dataset.pVote){voteDetail(b.dataset.pVote);return;}
    if(b.dataset.pDossier){dossier(b.dataset.pDossier);return;}
    if(b.dataset.pSummary){summary(b.dataset.pSummary);return;}
    if(b.dataset.pAsk){runAsk(b.dataset.pAsk);return;}
    if(b.dataset.pEvent){const kind=b.dataset.pEvent,id=b.dataset.value;if(kind==='vote')voteDetail(id);else if(kind==='project')projectDetail(id);else if(kind==='records')C.recordTable(C.person(id));else C.profile(id);return;}
    switch(b.dataset.p){
      case 'motion': state.motion=!state.motion && !reduced.matches;document.body.dataset.motion=state.motion?'on':'off';document.documentElement.style.scrollBehavior=state.motion?'smooth':'auto';save('clareia-motion',state.motion);b.setAttribute('aria-pressed',state.motion);b.textContent=motionText();watchMotion();break;
      case 'clear-highlight':state.highlightCategory=null;updateSpending();focusMatch('.donut-legend button:not(:disabled)');break;
      case 'spend-evidence':expenseEvidence();break;
      case 'map-evidence':C.showDialog('Como calculamos o mapa?',`<p class="records-note">${C.state.year} · jan–dez · ${state.mapMetric==='projects'?'autoria principal':C.state.category}</p><p>UF de representação, não destino da despesa. Média por representante = soma dos reembolsos dividida pelo número de perfis da UF; não ajusta tempo em exercício.</p><table class="data-table"><thead><tr><th>UF</th><th>Perfis</th><th>Valor</th></tr></thead><tbody>${['SP','MG','RJ'].map(uf=>`<tr><td>${uf}</td><td>${C.all().filter(p=>p.uf===uf).length}</td><td>${mapFormat(mapValue(uf))}</td></tr>`).join('')}</tbody></table><p class="fixture-note">Amostra fictícia, sem inferência sobre as bancadas reais. Demais UFs indisponíveis. Quantidade de projetos não mede qualidade.</p>`);break;
      case 'map-reset':state.mapUF='SP';renderPart('atlas',atlas);break;
      case 'apply-state':{const local=C.all().filter(p=>p.uf===state.mapUF);state.a=local[0].id;state.b=(local[1]||local[0]).id;C.state.uf=state.mapUF;C.refresh();}C.toast(`Recorte aplicado: ${UF[state.mapUF][0]}.`);break;
      case 'swap':[state.a,state.b]=[state.b,state.a];renderPart('comparacao',comparison);focusMatch('[data-p="swap"]');break;
      case 'compare-evidence':C.evidence(state.a,{kind:'gastos',compare:state.b});break;
      case 'ask-comparison':runAsk(`Compare ${C.person(state.a).name} e ${C.person(state.b).name} em ${C.state.year}${C.state.metric==='mensal'?' por mês':''}${C.state.category!=='Todas'?' com '+C.state.category:''}`);break;
      case 'clear-projects':state.topic='Todos';state.stage='Todos';state.projectQuery='';renderPart('projetos',projectSection);watchMotion();break;
      case 'clear-directory':state.rosterQuery='';state.rosterUF='Todos';state.rosterParty='Todos';renderPart('pessoas',directory);$('#roster-query')?.focus();break;
      case 'brief':brief();break;
      case 'assistant':if(editorial){$('#query').scrollIntoView({block:'center',behavior:state.motion?'smooth':'instant'});$('#query').focus({preventScroll:true});}else assistant();break;
      case 'top':window.scrollTo({top:0,behavior:state.motion?'smooth':'instant'});break;
      case 'coverage':C.showDialog('Cobertura desta demonstração',`<div class="text-content"><h3>Uma amostra pequena, declarada.</h3><p>Cinco perfis fictícios de deputados, três estados (SP, MG, RJ), anos 2024 e 2025. Gastos, projetos e participações são ilustrativos.</p><p>O mapa oferece as 27 UFs, mas 24 delas não têm dados nesta amostra. As propostas, votos nominais, eventos e dossiês são cenários independentes, identificados como fictícios.</p><p>Não há API oficial, IA conectada, processamento externo de perguntas ou envio de alertas. Favoritos ficam no armazenamento local do navegador.</p><h3>Próxima etapa de produto</h3><p>Validar fontes e métricas, conectar a base oficial e medir a qualidade das respostas antes de disponibilizar um assistente real.</p></div>`);break;
      case 'reset-saved':state.favorites.clear();state.projects.clear();save('clareia-favorites',[]);save('clareia-projects',[]);updateAll();$('#saved-count').textContent='';C.toast('Favoritos locais apagados.');break;
    }
  });
  document.addEventListener('input',e=>{
    if(e.target.id==='linked-from'||e.target.id==='linked-to'){const isFrom=e.target.id==='linked-from';state[isFrom?'from':'to']=+e.target.value;if(state.from>state.to)state[isFrom?'to':'from']=+e.target.value;$('#linked-from').value=state.from;$('#linked-to').value=state.to;$('#linked-from-label').textContent=months[state.from-1];$('#linked-to-label').textContent=months[state.to-1];$('#linked-result').innerHTML=linkedChart();}
    if(e.target.id==='spend-range'){state.month=+e.target.value;updateSpending();}
    if(e.target.id==='project-search'){state.projectQuery=e.target.value;renderPart('project-grid',projectCards);watchMotion();}
    if(e.target.id==='roster-query'){state.rosterQuery=e.target.value;renderPart('directory-grid',directoryCards);}
  });
  document.addEventListener('change',e=>{
    const id=e.target.id,val=e.target.value;
    if(id==='map-metric'){state.mapMetric=val;renderPart('atlas',atlas);focusMatch('#map-metric');}
    if(id==='map-select'){state.mapUF=val;renderPart('atlas',atlas);focusMatch('#map-select');}
    if(id==='compare-a'||id==='compare-b'){const k=id==='compare-a'?'a':'b',other=k==='a'?'b':'a';if(state[other]===val)state[other]=state[k];state[k]=val;renderPart('comparacao',comparison);focusMatch('#'+id);if(editorial&&id==='compare-a'){state.voter=val;state.timeline=val;renderPart('votacoes',voteSection);renderPart('acompanhar',following);watchMotion();focusMatch('#compare-a');}}
    if(id==='project-stage'){state.stage=val;renderPart('project-grid',projectCards);watchMotion();}
    if(id==='voter'){state.voter=val;renderPart('vote-grid',voteCards);watchMotion();}
    if(id==='timeline-person'){state.timeline=val;renderPart('acompanhar',following);watchMotion();focusMatch('#timeline-person');}
    if(id==='roster-uf'||id==='roster-party'){state[id==='roster-uf'?'rosterUF':'rosterParty']=val;renderPart('directory-grid',directoryCards);}
  });
  document.addEventListener('submit',e=>{if(e.target.id==='assistant-form'){e.preventDefault();const q=$('#assistant-query').value.trim();if(q)runAsk(q);}});
  document.addEventListener('keydown',e=>{if(e.target.matches('[data-p-uf]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&!$('#detail').open){e.preventDefault();$('#query').focus();$('#query').scrollIntoView({block:'center',behavior:state.motion?'smooth':'instant'});}});
  let ticking=false;
  addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(()=>{const max=document.documentElement.scrollHeight-innerHeight;$('.page-progress i').style.width=`${max?scrollY/max*100:0}%`;spySections();document.body.classList.toggle('past-hero',scrollY>innerHeight*.9);ticking=false;});ticking=true;}},{passive:true});
  document.addEventListener('pointermove',e=>{if(C.model!=='explorador'||!state.motion||e.pointerType==='touch')return;const card=e.target.closest('.dossier-card,.project-card');if(!card)return;const r=card.getBoundingClientRect();card.style.setProperty('--tilt-x',`${-(e.clientY-r.top-r.height/2)/r.height*3}deg`);card.style.setProperty('--tilt-y',`${(e.clientX-r.left-r.width/2)/r.width*3}deg`);});
  document.addEventListener('pointerout',e=>{const card=e.target.closest('.dossier-card,.project-card');if(card&&!card.contains(e.relatedTarget)){card.style.setProperty('--tilt-x','0deg');card.style.setProperty('--tilt-y','0deg');}});
  reduced.addEventListener('change',e=>{if(e.matches){state.motion=false;document.body.dataset.motion='off';$('.motion-toggle').setAttribute('aria-pressed','false');$('.motion-toggle').textContent=motionText();watchMotion();}});
  mount();
})();
